#include <bits/stdc++.h>
using namespace std;

struct DisjointSetUnion {
    vector<int> parent, size;
    void initialize(int n) {
        parent.resize(n);
        size.resize(n);
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
            size[i] = 1;
        }
    }
    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a != b) {
            if (size[a] < size[b]) swap(a, b);
            parent[b] = a;
            size[a] += size[b];
        }
    }
};

long long mod_pow(long long base, int exp, int modulus) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % modulus;
        base = (base * base) % modulus;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    const int MOD = 1e9 + 7;
    if (k == 0) {
        cout << mod_pow(n, n - 1, MOD) << "\n";
        return 0;
    }
    DisjointSetUnion dsu;
    dsu.initialize(n);
    for (int i = 0; i < n; ++i) {
        dsu.unite(i, (long long)i * k % n);
    }
    long long answer = 1;
    for (int i = 0; i < n; ++i) {
        if (dsu.find(i) != i) continue;
        long long t = mod_pow(k, dsu.size[i], n);
        if (t == 1) {
            answer = (answer * n) % MOD;
        }
    }
    cout << answer << "\n";
}
